M.ebmpRegelungen=R;
M.ebmpKohorte=function(neu){var s=S();if(!s)return null;if(neu!==undefined){if(neu===null)delete s.ebmpKohorte;else if(R[neu])s.ebmpKohorte=neu;try{M.save&&M.save();}catch(e){}}return s.ebmpKohorte&&R[s.ebmpKohorte]?s.ebmpKohorte:null;};
